(48318, 'itIT', 'Incarico di lavoro: Elisir di Sangue della Luce', '', '', '', '', '', '', '', '', 25549),
(48305, 'itIT', 'La congrega infuocata', 'Sconfiggi la Congrega delle Shivarra ad Antorus, il Trono Infuocato.', 'Nemmeno un Titano potrebbe resistere alle loro torture. Distruggi la Congrega delle Shivarra.', '', '', '', '', '', '', 25549),
(48304, 'itIT', 'Il Cacciatore d''Anime', 'Sconfiggi Imonar il Cacciatore d''Anime ad Antorus, il Trono Infuocato.', 'Imonar è il più letale cacciatore di taglie mai uscito dalla Distorsione Fatua. Trova una fossa e gettalo dentro.', '', '', '', '', '', '', 25549),
(48303, 'itIT', 'L''Alto Comando degli Antoran', 'Sconfiggi l''Alto Comando degli Antoran ad Antorus, il Trono Infuocato.', 'La Legione ha passato oltre 10.000 anni a pianificare l''invasione di Azeroth. Sconfiggi i loro capi, così che non possano più minacciare il nostro mondo.', '', '', '', '', '', '', 25549),
(48301, 'itIT', 'La congrega infuocata', 'Sconfiggi la Congrega delle Shivarra ad Antorus, il Trono Infuocato.', 'Nemmeno un Titano potrebbe resistere alle loro torture. Distruggi la Congrega delle Shivarra.', '', '', '', '', '', '', 25549),
