UPDATE `quest_template_locale` SET `LogDescription`='Ottieni 7 Costole di Ghoul dai Cadaveri Fetidi al Maniero dei Foscomanto.', `QuestDescription`='È un miracolo che i non morti non mi abbiano ancora divorato! Giusto ieri un branco di Ghoul stava attaccando le mura della mia torre!$B$BVoglio creare un''effige, una specie di "spaventapasseri" per i Ghoul. Per farlo mi servono delle Costole di Ghoul. Ce ne sono in abbondanza addosso ai Cadaveri Fetidi che infestano i terreni del Maniero dei Foscomanto, a nord di Borgoscuro...$B$BPortami le costole e in cambio ti darò delle monete.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=26677 AND `locale`='itIT');
